'use strict';
const $=id=>document.getElementById(id);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const imageUrl=p=>p.image.startsWith('https://')?p.image:`assets/${p.image}`;
let catalog=[],revision='',saving=false;
async function api(url,options={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers}});const result=await response.json();if(!response.ok){if(response.status===401&&url.includes('products'))showLogin();throw new Error(result.error||'Please try again.');}return result;}
function message(text,error=false){$('admin-message').textContent=text;$('admin-message').classList.toggle('error',error);}
function showLogin(){$('dashboard').hidden=true;$('login-panel').hidden=false;$('logout').hidden=true;}
function showDashboard(){$('dashboard').hidden=false;$('login-panel').hidden=true;$('logout').hidden=false;}
function render(){
 $('total-products').textContent=catalog.length;$('active-products').textContent=catalog.filter(p=>p.active).length;$('hidden-products').textContent=catalog.filter(p=>!p.active).length;
 const query=$('admin-search').value.toLowerCase();const list=catalog.filter(p=>`${p.name} ${p.category}`.toLowerCase().includes(query));
 $('catalog-rows').innerHTML=list.map(p=>`<tr><td><div class="table-product"><img src="${esc(imageUrl(p))}" alt=""><div><strong>${esc(p.name)}</strong><small>${esc(p.id)}</small></div></div></td><td>${esc(p.category)}</td><td>${new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(p.price)}</td><td><span class="status ${p.active?'':'hidden'}">${p.active?'Visible':'Hidden'}</span></td><td><div class="row-actions"><button data-edit="${esc(p.id)}">Edit</button><button data-toggle="${esc(p.id)}" ${saving?'disabled':''}>${p.active?'Hide':'Show'}</button></div></td></tr>`).join('');$('catalog-empty').hidden=list.length>0;$('catalog-empty').textContent=catalog.length?'No products match your search.':'No products yet. Add your first product.';
}
async function load(){const result=await api('/api/products?admin=1');catalog=result.products;revision=result.revision;render();}
async function save(next){if(saving)throw new Error('A save is already in progress.');saving=true;$('save-product').disabled=true;render();try{const result=await api('/api/products',{method:'PUT',body:JSON.stringify({products:next,revision})});catalog=result.products;revision=result.revision;render();message('Changes saved. Your storefront is updated.');}finally{saving=false;$('save-product').disabled=false;render();}}
function edit(id){const p=catalog.find(p=>p.id===id);const form=$('product-form');form.reset();$('editor-error').textContent='';$('editor-title').textContent=p?'Edit product':'Add product';for(const field of ['id','name','category','price','mrp','tag','image','description','rating','reviews'])form.elements[field].value=p?.[field]??(field==='category'?'Electronics':['rating','reviews'].includes(field)?0:'');form.elements.specs.value=p?.specs.join('\n')||'';form.elements.active.checked=p?.active??true;$('editor').showModal();}
$('login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;message('');try{await api('/api/session',{method:'POST',body:JSON.stringify({password:$('password').value})});$('password').value='';await load();showDashboard();}catch(e){message(e.message,true);}finally{button.disabled=false;}});
$('logout').addEventListener('click',async()=>{try{await api('/api/session',{method:'DELETE'});catalog=[];revision='';showLogin();message('Signed out.');}catch(e){message(e.message,true);}});
$('new-product').addEventListener('click',()=>edit());
$('close-editor').addEventListener('click',()=>$('editor').close());$('cancel-editor').addEventListener('click',()=>$('editor').close());
$('admin-search').addEventListener('input',render);
$('refresh').addEventListener('click',async()=>{try{await load();message('Catalog refreshed.');}catch(e){message(e.message,true);}});
$('catalog-rows').addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.edit)edit(button.dataset.edit);if(button.dataset.toggle){try{await save(catalog.map(p=>p.id===button.dataset.toggle?{...p,active:!p.active}:p));}catch(e){message(e.message,true);}}});
$('product-form').addEventListener('submit',async event=>{event.preventDefault();const f=event.target.elements;const id=f.id.value||`${f.name.value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)||'product'}-${crypto.randomUUID().slice(0,8)}`;const p={id,name:f.name.value.trim(),category:f.category.value,price:Number(f.price.value),mrp:Number(f.mrp.value),tag:f.tag.value.trim(),image:f.image.value.trim(),description:f.description.value.trim(),rating:Number(f.rating.value),reviews:Number(f.reviews.value),specs:f.specs.value.split('\n').map(v=>v.trim()).filter(Boolean),active:f.active.checked};$('editor-error').textContent='';if(p.mrp<p.price){$('editor-error').textContent='Original price cannot be lower than selling price.';return;}try{await save(catalog.some(item=>item.id===id)?catalog.map(item=>item.id===id?p:item):[...catalog,p]);$('editor').close();}catch(e){$('editor-error').textContent=e.message;}});
(async()=>{try{const session=await api('/api/session');if(session.authenticated){await load();showDashboard();}else{showLogin();if(!session.configured)message('Admin password has not been configured. Contact the store owner.',true);}}catch(e){message(e.message,true);}})();
